# Runtime v2 · B0 Bản đồ toàn cảnh (viết lại sau cùng; giữ sim runtime.map và mục v1 'roles', 'theme')
# Tổng hợp từ các chương v2. Sửa luôn hai câu cũ "androidx-main, đọc 2026-11-21" trong callout của sim compiler và applier (nay ghim commit 296313a4).

SEC_ORDER = {'b0': ['hook', 'roles', 'order', 'index', 'theme']}

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    C = 'b0'
    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', 'Bạn bấm một nút làm đổi một số trên màn hình. Theo bạn, Compose có chạy lại TOÀN BỘ hàm `@Composable` của màn hình không?', 'You tap a button that changes a number on screen. Do you think Compose re-runs the screen\'s WHOLE `@Composable` function?')
    B(C, S, 1, 'ans', 'Không nhất thiết. Chỉ scope đã ĐỌC state bị đổi mới bị invalidate; trong lượt chạy lại, composable con có tham số không đổi có thể được skip; và tùy nơi state được đọc, có khi chỉ layout hay draw chạy lại mà không có composition. Cả track này giải thích vì sao, từng thành phần một.', 'Not necessarily. Only the scope that READ the changed state is invalidated; during the re-run, child composables with unchanged arguments may be skipped; and depending on where the state is read, sometimes only layout or draw re-runs, with no composition at all. This whole track explains why, one component at a time.')

    S = 'order'
    a(C + '.sec.%s.title' % S, 'Thứ tự đọc của track', 'The track\'s reading order')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Track đi từ cách nghĩ tới cơ chế, rồi tới thực hành:\n• Nền tảng: DC (tư duy khai báo, tính chất của composable), B1 (setContent và host), B2 (compiler biến đổi gì: group, `$changed`, restart, skip), B3 (SlotTable, identity, `key`).\n• State: B4 (State và Snapshot, policy, `derivedStateOf`), SH (stateless, hoisting, ai giữ state, sống qua đổi cấu hình), B5 (Recomposer và frame clock), EF (side effect và vòng đời), CL (CompositionLocal và slot API).\n• Từ composition tới pixel: B6 (Composer ghi nhận, Applier áp dụng), B7 (ba phase, đọc state theo phase), LO (constraints, một lượt đo, Layout tùy chỉnh, intrinsic, SubcomposeLayout), MD (thứ tự modifier, element và Modifier.Node), LZ (lazy list, key, contentType, dùng lại slot).\n• Tối ưu và kiểm: B8 (stability, strong skipping, annotation của runtime), B9 (semantics, accessibility, kiểm thử UI), PF (đo đúng và năm thực hành), B10 (luồng +1 qua tám bước).', 'The track moves from mindset to mechanism, then to practice:\n• Foundations: DC (declarative thinking, properties of composables), B1 (setContent and the host), B2 (what the compiler transforms: groups, `$changed`, restart, skip), B3 (SlotTable, identity, `key`).\n• State: B4 (State and Snapshot, policies, `derivedStateOf`), SH (stateless, hoisting, who owns state, surviving configuration changes), B5 (the Recomposer and the frame clock), EF (side effects and lifecycle), CL (CompositionLocal and slot APIs).\n• From composition to pixels: B6 (the Composer records, the Applier applies), B7 (three phases, phased state reads), LO (constraints, single-pass measurement, custom layouts, intrinsics, SubcomposeLayout), MD (modifier order, elements and Modifier.Node), LZ (lazy lists, keys, contentType, slot reuse).\n• Optimising and checking: B8 (stability, strong skipping, runtime annotations), B9 (semantics, accessibility, UI testing), PF (measuring correctly and five practices), B10 (the +1 flow through eight steps).')

    S = 'index'
    a(C + '.sec.%s.title' % S, 'Gặp vấn đề này thì đọc chương nào', 'Which chapter to read for which problem')
    a(C + '.sec.%s.badge' % S, 'guideline')
    B(C, S, 1, 'p', '• UI không cập nhật khi dữ liệu đổi: B4 (state không quan sát được), SH, B10 bước 1–3.\n• State mất khi xoay màn hình hay sau khi xóa một mục: SH (`rememberSaveable`), B3 và LZ (`key`).\n• Một composable recompose quá nhiều: B8 (stability), PF (`derivedStateOf`, hoãn lần đọc), B7.\n• Coroutine chạy sai lúc, bị hủy hay chạy lại: EF, rồi chương A8 của track Coroutines.\n• Giao diện nháy hoặc lệch một frame: B7 (vòng lặp `onSizeChanged`), PF (ghi ngược).\n• Crash "measure() may not be called multiple times" hay lồng cuộn: LO, LZ.\n• Modifier không có tác dụng hoặc sai thứ tự: MD.\n• TalkBack đọc sai, test không tìm thấy node: B9.', '• The UI does not update when data changes: B4 (unobservable state), SH, B10 steps 1–3.\n• State is lost on rotation or after deleting an item: SH (`rememberSaveable`), B3 and LZ (`key`).\n• A composable recomposes too often: B8 (stability), PF (`derivedStateOf`, deferred reads), B7.\n• A coroutine runs at the wrong time, is cancelled or restarts: EF, then chapter A8 of the Coroutines track.\n• The UI flickers or is one frame off: B7 (the `onSizeChanged` loop), PF (backwards writes).\n• A "measure() may not be called multiple times" crash or nested scrolling: LO, LZ.\n• A modifier has no effect or applies in the wrong order: MD.\n• TalkBack reads things wrongly, or a test cannot find a node: B9.')

    for q, qv, qe, av, ae, wv, we in [
        ('q3', 'State bị mất khi xóa một mục trong LazyColumn: đọc chương nào trước?', 'State is lost when deleting an item in a LazyColumn: which chapter first?',
         'LZ (key), rồi B3.', 'LZ (keys), then B3.', 'Không có key thì state gắn với vị trí.', 'Without keys, state is tied to position.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)

def override(o):
    C = 'b0'
    o(C + '.essence',
      'Compose Runtime gồm nhiều vai trò: host, Composition, Recomposer, mã đã được compiler biến đổi, Composer, SlotTable, Snapshot, Applier, cây UI (LayoutNode), các phase và cây semantics. Mỗi vai trò làm một việc. Gộp tất cả thành một "engine" mơ hồ thì khó hiểu vì sao một thay đổi nhỏ chỉ làm chạy lại một phần nhỏ.\nBản đồ bên dưới được dùng lại suốt track; mỗi thành phần trỏ tới chương nói chi tiết về nó. Phần còn lại của chương là thứ tự đọc, và một "chỉ mục theo triệu chứng" để tra khi gặp bug.\nTrình duyệt không chạy Compose Runtime thật. Site là một mô hình giảng dạy, với chi tiết nội bộ ghim ở một commit AndroidX cụ thể.\nQuy tắc dễ nhớ: Compose không phải một cỗ máy, mà là một đội; biết ai làm việc gì thì biết bug nằm ở đâu.',
      'The Compose Runtime has many roles: the host, the Composition, the Recomposer, compiler-transformed code, the Composer, the SlotTable, Snapshots, the Applier, the UI tree (LayoutNodes), the phases and the semantics tree. Each role does one job. Lumping them all into one vague "engine" makes it hard to see why a small change re-runs only a small part.\nThe map below is reused throughout the track; each component points to the chapter that covers it in detail. The rest of this chapter is the reading order, and a "symptom index" to look things up when you hit a bug.\nThe browser does not run the real Compose Runtime. The site is a teaching model, with internal details pinned to a specific AndroidX commit.\nRule of thumb: Compose is not one machine but a team; know who does what and you know where a bug lives.')
    o('m.map.wrapup', 'Composition, Recomposer, Composer và Applier là bốn vai trò khác nhau, không phải một "engine". Các chương từ DC tới B10 xem từng vai trò thật kỹ; thứ tự đọc ở ngay dưới bản đồ.', 'The Composition, Recomposer, Composer and Applier are four different roles, not one "engine". The chapters from DC to B10 look at each role in depth; the reading order is right below the map.')
    o('m.compiler.co.impl', 'Restart group và update scope được mô tả trong tài liệu thiết kế của runtime (ghim androidx-main commit 296313a4, 2026-11-21). [[badge:impl]] [[src:rt-how]]', 'Restart groups and update scopes are described in the runtime design document (pinned to androidx-main commit 296313a4, 2026-11-21). [[badge:impl]] [[src:rt-how]]')
    o('m.applier.co.coalesce', 'Tài liệu thiết kế runtime mô tả việc gộp thao tác node liền kề thành một lời gọi Applier (ghim androidx-main commit 296313a4, 2026-11-21). [[badge:impl]] [[src:rt-how]]', 'The runtime design document describes merging adjacent node operations into one Applier call (pinned to androidx-main commit 296313a4, 2026-11-21). [[badge:impl]] [[src:rt-how]]')
